private async fetchBugsByFeatures(featureIds: number[]): Promise<ClosedBug[]> {
  const storyIds: number[] = [];
  for (const featureId of featureIds) {
    const ids = await this.adoClient.getStoryIdsByFeature(featureId);
    storyIds.push(...ids);
  }

  // Dedup: two features can share a story — without this its bugs would test/count twice
  const uniqueStoryIds = Array.from(new Set(storyIds));
  const allBugs: ClosedBug[] = [];

  for (const storyId of uniqueStoryIds) {
    const wi = await this.adoClient.getWorkItemWithRelations(storyId);
    const childIds = this.extractChildIds(wi.relations || []);
    const storyTitle = wi.fields?.['System.Title'] || '';

    for (const childId of childIds) {
      const child = await this.adoClient.getWorkItemWithRelations(childId);
      const fields = child.fields || {};
      // Only FIXED bugs — the whole job is re-verifying resolved work, not open tickets
      if (
        fields['System.WorkItemType'] === 'Bug' &&
        (fields['System.State'] === 'Closed' || fields['System.State'] === 'Resolved')
      ) {
        allBugs.push(this.mapToBug(child, storyId, storyTitle));
      }
    }
  }
  return allBugs;
}

// Elsewhere: sort so P1 bugs always run before P2/P3/P4 (matters under --limit)
// priority ascending = P1 first; severity.localeCompare only breaks ties WITHIN a priority
bugs.sort((a, b) => a.priority - b.priority || a.severity.localeCompare(b.severity));

function analyzeTestability(bug: ClosedBug): TestabilityResult {
  // One haystack from all 4 sources — a disqualifying keyword is caught wherever it lives
  const combined = `${bug.title} ${bug.reproStepsText} ${bug.descriptionText} ${bug.tags.join(' ')}`;

  // Exit 1 (cheapest): browser-impossible checks — mic, visual judgment, etc.
  const skipReason = findSkipReason(combined);
  if (skipReason) {
    return { automatable: false, mode: 'skip', skipReason, testDescription: '', actions: [] };
  }

  // Exit 2: too little text to build reliable steps — either field clearing 20 chars is enough
  const hasContent = bug.reproStepsText.length >= 20 || bug.descriptionText.length >= 20;
  if (!hasContent) {
    return { automatable: false, mode: 'skip', skipReason: 'Repro steps too vague (< 20 chars)', testDescription: '', actions: [] };
  }

  // Exit 3: can't map the bug to a known testable flow
  const mode = detectMode(combined);
  if (mode === 'skip') {
    return { automatable: false, mode: 'skip', skipReason: 'Cannot map bug to a testable mode', testDescription: '', actions: [] };
  }

  // Passed all gates -> build the concrete plan (empty actions here would mean a SKIP, not a FAIL)
  const actions = buildActions(mode, bug);
  const testDescription = buildTestDescription(mode, bug);
  return { automatable: true, mode, skipReason: '', testDescription, actions };
}

function buildActions(mode: TestMode, bug: ClosedBug): ActionStep[] {
  const lower = `${bug.title} ${bug.reproStepsText}`.toLowerCase(); // keyword routing, case-insensitive
  const actions: ActionStep[] = [];

  // Always orient first: load the app, start a fresh session — a stale session causes false FAILs
  actions.push({ type: 'navigate', description: 'Navigate to the app and verify page loads' });
  actions.push({ type: 'newChat',  description: 'Start a fresh session' });

  if (mode === 'teacher') {
    actions.push({ type: 'enterTeacherMode', description: 'Enter learning mode' });

    if (lower.includes('quiz')) {
      // Canonical send -> wait -> assert triple
      actions.push({ type: 'sendMessage', payload: { message: 'Give me a quiz on project management.' }, description: 'Request a quiz' });
      actions.push({ type: 'waitForResponse', description: 'Wait for quiz question' });
      // minLength 50: an empty/near-empty reply = FAIL, catching a silently-broken feature
      actions.push({ type: 'assertResponseLength', payload: { minLength: 50 }, description: 'Assert quiz question returned' });
    }
    // ... other sub-cases (summary, history, chapter) follow the same pattern
  }
  // ... 'student' and 'navigation' modes are handled the same way

  actions.push({ type: 'screenshot', description: 'Capture final state' }); // always — evidence for pass OR fail
  return actions; // plain data objects, not calls — executeAction interprets them later
}

private async executeAction(action: ActionStep): Promise<void> {
  const page = this.page!;

  switch (action.type) {
    case 'sendMessage': {
      const message: string = action.payload?.message || 'Hello'; // default so a payload-less step still sends
      const chatInput = page.locator(SEL.chatInput).first(); // .first() guards against a multi-match selector
      // Wait for visibility so a slow render becomes a clean timeout, not a fill-on-detached error
      await chatInput.waitFor({ state: 'visible', timeout: 10000 });
      await chatInput.fill(message);
      await page.keyboard.press('Enter');
      break;
    }

    case 'waitForResponse': {
      const deadline = Date.now() + 90000; // hard 90s cap so a hung response can't stall the run
      while (Date.now() < deadline) {
        // .catch(()=>false): if the indicator was already removed the check throws — treat as "done"
        const thinking = await page.locator(SEL.thinkingText).isVisible().catch(() => false);
        if (!thinking) { await page.waitForTimeout(1500); break; } // done -> one settle beat, then proceed
        await page.waitForTimeout(1000); // still thinking -> poll again in 1s
      }
      break;
    }
    // ... other cases: assertElementVisible, uploadFile, screenshot, etc.
  }
}

private async executeBugTest(bug: ClosedBug, testability: TestabilityResult, appUrl: string): Promise<BugTestResult> {
  const start = Date.now();
  try {
    await this.resetPageState(appUrl); // isolate this bug from the previous one's residue
    for (const action of testability.actions) {
      await this.executeAction(action); // sequential — order IS the test; any throw = the fix regressed
    }
    const screenshotPath = await this.takeScreenshot(bug.id, 'pass'); // reaching here without throwing = PASS
    return {
      bugId: bug.id, bugTitle: bug.title, priority: bug.priority,
      mode: testability.mode, status: 'PASS',
      screenshotPath, durationMs: Date.now() - start, actions: testability.actions,
    };
  } catch (err: any) {
    // .catch(()=>undefined): don't let a failed fail-screenshot throw out of the handler
    const screenshotPath = await this.takeScreenshot(bug.id, 'fail').catch(() => undefined);
    return {
      bugId: bug.id, bugTitle: bug.title, priority: bug.priority,
      // String(err) normalizes non-Error throws; slice caps the message for a readable report
      mode: testability.mode, status: 'FAIL', error: (err.message || String(err)).slice(0, 250),
      screenshotPath, durationMs: Date.now() - start, actions: testability.actions, // timing recorded even on FAIL
    };
  }
}

private buildReport(results: BugTestResult[], bugs: ClosedBug[], input: AgentInput, appUrl: string): ReleaseReport {
  const tested   = results.filter(r => r.status !== 'SKIP'); // SKIPs are excluded from the denominator
  const passed   = results.filter(r => r.status === 'PASS').length;
  const failed   = results.filter(r => r.status === 'FAIL').length;
  const skipped  = results.filter(r => r.status === 'SKIP').length;
  // Rate over verifiable bugs only; guard divide-by-zero on an all-skipped run
  const passRate = tested.length > 0 ? Math.round((passed / tested.length) * 100) : 0;

  // P1 rate computed separately — this is the hard gate; a failed P1 should stop the ship
  const p1Results = results.filter(r => r.priority === 1 && r.status !== 'SKIP');
  const p1Passed  = p1Results.filter(r => r.status === 'PASS').length;

  return {
    generatedAt: new Date().toISOString(), appUrl,
    summary: {
      totalBugs: bugs.length, automatable: tested.length, skipped, passed, failed,
      passRate, p1Bugs: p1Results.length, p1Passed,
    },
    results,
  };
}
